bigTreeIteration="10"                                       # Iteration number (within step 11's rogue-removal loop) at which processing switches from the regular per-round loop into the "big tree" branch, which rebuilds using the full sequence set (--allSeqs) for up to bigNumRoundsLeft more rounds. Default: 10.
bigNumRoundsLeft="10"                                       # Max number of rounds to run once the "big tree" branch above starts. Default: 10.
aligner=$("$DIR/../PhylogenyPipeline/GetDefaultAligner.sh") # Alignment program used to build/refine sequence alignments - follows the pipeline's own default (PhylogenyPipeline/GetDefaultAligner.sh; currently FAMSA) unless overridden here. See 09_AlignWith*.sh for the full list of options (MAGUS, PASTA, MAFFT, MUSCLE5, etc.).
continue="--continue"                                       # Whether each script automatically continues into the pipeline's next stage after finishing its own step(s), instead of stopping so output can be checked first. Default: --continue (use "" to stop instead, as the -NoContinue scripts do).
numRoundsLeft="20"                                          # Max number of align/build-tree/remove-rogues rounds to run (steps 9 to 11's loop) before stopping. Default: 20.
shuffleSeqs="--shuffleSeqs"                                 # Shuffle sequence order between rogue-removal rounds, to avoid a deterministic processing-order bias - this should be left on. Default: --shuffleSeqs.
extension="contree"                                         # Tree file extension (IQ-TREE's consensus tree output) used to pick which tree files to extract sequences of interest from. Default: contree.
trimAl="Default"                                            # trimAl trimming threshold: "Default" uses trimAl's own default heuristic (around 0.1), or a specific value between 0.0 and 1.0. Default: Default. Applies to `aligner` (the main aligner) only, and only directly - every 16_TreeBuildScheduler.sh call also automatically submits one comparison round for the main aligner with this setting flipped (a `*.BigTree0.noTrimAl` tree if trimAl is set here, `*.BigTree0.trimAl` if it's unset), so both variants exist for whichever aligner is currently "main" regardless of this value. See README's Running/16_TreeBuildScheduler.sh.
useFullDataset="--useFullDataset"                           # Skip the pruning-guide-tree step (step 13) and hand the aligner the full non-redundant sequence set directly - fine if it's small enough to align/build a tree from without pruning first. Default: --useFullDataset (leave unset to prune with a guide tree first).
runPMSF=""                                                  # Automatically submit step 18 (PMSF, site-heterogeneous LG+C20+F+G refinement) once rogue-removal genuinely finishes on this gene's real, final branch (the regular loop if bigTreeIteration != "0", or the BigTree0/BigTreeN branch if that is the real path) - never on comparison rounds (other aligners, the outgroup-free variant, the trimAl/noTrimAl comparison). Default: "" (off); set to "--runPMSF" to enable. Expensive (~42.6h on PRRs' ~1100-taxon scale, confirmed 2026-10-12) - see 18_RefineTreeWithPMSF.sh/Scheduler-18-RefineTreeWithPMSF.sh before turning this on for a much larger gene family.
localNr=""                                                  # Search/extract NCBI's nr database from a local BLAST copy instead of over the network - see PhylogenyPipeline/ProteinDatabase/get_ncbi_blastdb.sh (built automatically once needed) and the README's "Databases" section. Default: "" (remote); use --localNr to enable.
localRefseqProtein=""                                       # Search/extract NCBI's refseq_protein database from a local BLAST copy instead of over the network - see PhylogenyPipeline/ProteinDatabase/get_ncbi_blastdb.sh (built automatically once needed) and the README's "Databases" section. Default: "" (remote); use --localRefseqProtein to enable.
localTsaNr=""                                               # Search/extract NCBI's tsa_nr database from a local BLAST copy instead of over the network - see PhylogenyPipeline/ProteinDatabase/get_ncbi_blastdb.sh (built automatically once needed) and the README's "Databases" section. Default: "" (remote); use --localTsaNr to enable.
